# Region 3: 7x7 hollow → 7x7 solid block at rows 1-7, cols 14-20
# Region 0: 6x6 hollow → 6x6 solid block at rows 2-7, cols 1-6
# Region 6: 3x3 hollow → 3x3 solid block at rows 5-7, cols 9-11

def create_filled_output():
    # Start with background 9
    output = [[9 for _ in range(27)] for _ in range(11)]

    # Fill region 3 (7x7): rows 1-7, cols 14-20
    for r in range(1, 8):
        for c in range(14, 21):
            output[r][c] = 3

    # Fill region 0 (6x6): rows 2-7, cols 1-6
    for r in range(2, 8):
        for c in range(1, 7):
            output[r][c] = 0

    # Fill region 6 (3x3): rows 5-7, cols 9-11
    for r in range(5, 8):
        for c in range(9, 12):
            output[r][c] = 6

    return output

